// rehash.go — one-shot backfill repair for PR #520.
// Scrubs remaining personal path forms from tracked audit chunks and,
// for every line whose tool_input changes (now or in the earlier scrub
// pass, marked by [REDACTED: tokens), recomputes tool_input_hash and
// tool_input_preview with the exact writer logic (sha256 over
// json.Marshal of tool_input; preview = marshal truncated to 200) and
// sets redacted:true. Splices values into the raw line so field order
// and untouched bytes are preserved. --raw files get text scrub only.
package main

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

const previewLimit = 200

func scrubText(s string) string {
	s = strings.ReplaceAll(s, "-home-user-", "-home-user-")
	s = strings.ReplaceAll(s, "~/", "[REDACTED:home-path]")
	s = strings.ReplaceAll(s, "[REDACTED:home-path]", "[REDACTED:home-path]")
	s = strings.ReplaceAll(s, "~", "[REDACTED:home-path]")
	s = strings.ReplaceAll(s, "[REDACTED:home-path]", "[REDACTED:home-path]")
	return s
}

func scrubValue(v any) (any, bool) {
	switch t := v.(type) {
	case string:
		n := scrubText(t)
		return n, n != t
	case map[string]any:
		changed := false
		for k, val := range t {
			nv, ch := scrubValue(val)
			t[k] = nv
			changed = changed || ch
		}
		return t, changed
	case []any:
		changed := false
		for i, val := range t {
			nv, ch := scrubValue(val)
			t[i] = nv
			changed = changed || ch
		}
		return t, changed
	default:
		return v, false
	}
}

func marshalTI(ti any) ([]byte, error) { return json.Marshal(ti) }

func processLine(line string) (string, bool, error) {
	needs := strings.Contains(line, "-home-user-") ||
		strings.Contains(line, "~") ||
		strings.Contains(line, "[REDACTED:home-path]")
	already := strings.Contains(line, "[REDACTED:")
	if !needs && !already {
		return line, false, nil
	}
	dec := json.NewDecoder(strings.NewReader(line))
	dec.UseNumber()
	var obj map[string]any
	if err := dec.Decode(&obj); err != nil {
		return line, false, fmt.Errorf("parse: %w", err)
	}
	oldHash, _ := obj["tool_input_hash"].(string)
	oldPrev, hadPrev := obj["tool_input_preview"].(string)
	ti, hasTI := obj["tool_input"]

	changed := false
	if hasTI && needs {
		var ch bool
		ti, ch = scrubValue(ti)
		changed = ch
	}
	if !hasTI {
		// nothing to rehash; only raw text scrub of the line (e.g.
		// preview-only or other fields) — not expected, bail to text.
		out := scrubText(line)
		return out, out != line, nil
	}

	data, err := marshalTI(ti)
	if err != nil {
		return line, false, fmt.Errorf("marshal: %w", err)
	}
	sum := sha256.Sum256(data)
	newHash := hex.EncodeToString(sum[:])
	s := string(data)
	newPrev := s
	if len(s) > previewLimit {
		newPrev = s[:previewLimit] + "..."
	}

	out := line
	if changed { // splice scrubbed tool_input: re-marshal whole? No — splice fields.
		// Replace the tool_input raw segment: find old marshal of the
		// ORIGINAL ti is unavailable post-mutation; instead rebuild the
		// line by marshaling obj with updated fields, preserving order
		// is impossible generically — so for changed tool_input we do
		// targeted text scrub of the raw line (same result, order kept).
		out = scrubText(out)
	}
	if oldHash != "" && oldHash != newHash {
		if strings.Count(out, oldHash) != 1 {
			return line, false, fmt.Errorf("hash occurs %d times", strings.Count(out, oldHash))
		}
		out = strings.Replace(out, oldHash, newHash, 1)
	}
	if hadPrev {
		oldPrevRaw, _ := json.Marshal(scrubText(oldPrev))
		newPrevRaw, _ := json.Marshal(newPrev)
		seg := `"tool_input_preview":` + string(oldPrevRaw)
		if strings.Count(out, seg) == 1 {
			out = strings.Replace(out, seg, `"tool_input_preview":`+string(newPrevRaw), 1)
		} else {
			// preview raw form drifted (earlier python pass): locate by key.
			i := strings.Index(out, `"tool_input_preview":"`)
			if i < 0 {
				return line, false, fmt.Errorf("preview key not found")
			}
			j := i + len(`"tool_input_preview":`)
			// scan the JSON string to its closing quote
			k := j + 1
			for k < len(out) {
				if out[k] == '\\' {
					k += 2
					continue
				}
				if out[k] == '"' {
					break
				}
				k++
			}
			out = out[:j] + string(newPrevRaw) + out[k+1:]
		}
	}
	if !strings.Contains(out, `"redacted":true`) {
		// append before closing brace
		if !strings.HasSuffix(out, "}") {
			return line, false, fmt.Errorf("line does not end with }")
		}
		out = out[:len(out)-1] + `,"redacted":true}`
	}
	// verify: parse, recompute, compare
	vdec := json.NewDecoder(strings.NewReader(out))
	vdec.UseNumber()
	var vo map[string]any
	if err := vdec.Decode(&vo); err != nil {
		return line, false, fmt.Errorf("verify parse: %w", err)
	}
	vdata, err := json.Marshal(vo["tool_input"])
	if err != nil {
		return line, false, err
	}
	vsum := sha256.Sum256(vdata)
	if got, _ := vo["tool_input_hash"].(string); got != hex.EncodeToString(vsum[:]) {
		return line, false, fmt.Errorf("verify hash mismatch")
	}
	return out, out != line, nil
}

func main() {
	raw := false
	changedTotal := 0
	for _, arg := range os.Args[1:] {
		if arg == "--raw" {
			raw = true
			continue
		}
		b, err := os.ReadFile(arg)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
		n := 0
		for i, line := range lines {
			if line == "" {
				continue
			}
			if raw {
				nl := scrubText(line)
				if nl != line {
					lines[i], n = nl, n+1
				}
				continue
			}
			nl, ch, err := processLine(line)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s:%d: %v\n", arg, i+1, err)
				os.Exit(1)
			}
			if ch {
				lines[i], n = nl, n+1
			}
		}
		if n > 0 {
			out := strings.Join(lines, "\n") + "\n"
			if err := os.WriteFile(arg, bytes.NewBufferString(out).Bytes(), 0o644); err != nil {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
		}
		fmt.Printf("%s: %d lines updated (raw=%v)\n", arg, n, raw)
		raw = false
	}
	fmt.Println("total-ok", changedTotal)
}

